// 密码重置功能 - 基于用户提供的令牌文件路径获取重置信息
const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const app = express();

app.use(express.json());

// 模拟用户数据库
const users = {
  'alice@example.com': { id: 1, resetToken: 'abc123', resetDir: 'alice' },
  'bob@example.com': { id: 2, resetToken: 'xyz789', resetDir: 'bob' }
};

// 密码重置接口 - 用户提供令牌，服务端读取对应文件
app.post('/api/reset-password', (req, res) => {
  const { email, token } = req.body;
  const user = users[email];

  if (!user || user.resetToken !== token) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // 构造重置信息文件路径
  const baseDir = '/var/reset-data/';
  const fileName = user.resetDir + '_reset_info.txt';

  // 防御尝试：替换路径分隔符，但遗漏了编码绕过
  const sanitizedFileName = fileName.replace(/[\/\\]/g, '_');

  // 此处路径拼接存在缺陷，用户可控的 resetDir 来自数据库（可能被污染）
  const filePath = path.join(baseDir, sanitizedFileName);

  try {
    // 读取文件内容并返回
    const content = fs.readFileSync(filePath, 'utf8');
    res.json({ resetInfo: content });
  } catch (err) {
    res.status(500).json({ error: 'Failed to read reset info' });
  }
});

