// app.js - Flask文件上传服务
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();
const upload = multer({ dest: 'uploads/' });

// 模拟用户会话存储（实际项目中用Redis/JWT）
const sessions = new Map();

// 登录接口 - 生成会话令牌
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (username === 'admin' && password === 'secret123') {
    const token = crypto.randomBytes(16).toString('hex');
    sessions.set(token, { user: 'admin', role: 'admin' });
    res.json({ token });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

// 辅助函数：检查会话有效性
function isAuthenticated(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return false;
  const token = authHeader.substring(7);
  return sessions.has(token);
}

// 文件上传接口 - 仅允许登录用户
app.post('/api/upload', upload.single('file'), (req, res) => {
  // 防御点：检查用户是否已认证
  if (!isAuthenticated(req)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const file = req.file;
  if (!file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  // 防御点：限制文件类型
  const allowedExt = ['.jpg', '.png', '.gif'];
  const ext = path.extname(file.originalname).toLowerCase();
  if (!allowedExt.includes(ext)) {
    fs.unlinkSync(file.path); // 清理临时文件
    return res.status(400).json({ error: 'File type not allowed' });
  }

  // 防御点：限制文件大小（multer已限制10MB）
  if (file.size > 10 * 1024 * 1024) {
    fs.unlinkSync(file.path);
    return res.status(400).json({ error: 'File too large' });
  }

  // 存储文件 - 使用随机文件名避免路径穿越
  const newFilename = crypto.randomBytes(8).toString('hex') + ext;
  const targetPath = path.join('uploads', newFilename);

  // 移动文件到目标位置
  fs.rename(file.path, targetPath, (err) => {
    if (err) {
      fs.unlinkSync(file.path);
      return res.status(500).json({ error: 'File save failed' });
    }
    res.json({ 
      message: 'Upload success', 
      fileUrl: `/files/${newFilename}`,
      uploadedBy: 'anonymous' // 漏洞点：未记录真实用户身份
    });
  });
});

// 文件访问接口 - 静态文件服务
app.get('/files/:filename', (req, res) => {
  const filename = req.params.filename;
  // 防御点：防止路径穿越
  if (filename.includes('..') || filename.includes('/')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  const filePath = path.join('uploads', filename);
  if (fs.existsSync(filePath)) {
    res.sendFile(path.resolve(filePath));
  } else {
    res.status(404).json({ error: 'File not found' });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

# nginx.conf - 服务编排网关配置
user  nginx;
worker_processes  auto;

events {
    worker_connections  1024;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    # 上游微服务集群
    upstream backend {
        server 10.0.1.10:8080 weight=3;
        server 10.0.1.11:8080 weight=2;
        keepalive 32;
    }

    # 缓存静态资源
    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=static_cache:10m max_size=1g inactive=60m use_temp_path=off;

    server {
        listen 443 ssl;
        server_name api.example.com;

        # 弱TLS配置 - 仅启用TLSv1和TLSv1.1，允许RC4-SHA密码套件
        ssl_protocols TLSv1 TLSv1.1;
        ssl_ciphers 'RC4-SHA:ECDHE-RSA-RC4-SHA:AES128-SHA';
        ssl_prefer_server_ciphers on;

        ssl_certificate     /etc/nginx/certs/api.crt;
        ssl_certificate_key /etc/nginx/certs/api.key;

        # 核心API路由
        location /api/ {
            proxy_pass http://backend;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

            # 限流保护
            limit_req zone=api_limit burst=20 nodelay;
            limit_req_status 429;
        }

        # 静态资源缓存
        location /static/ {
            proxy_cache static_cache;
            proxy_pass http://backend;
            proxy_cache_valid 200 60m;
            add_header X-Proxy-Cache $upstream_cache_status;
        }

        # 健康检查端点
        location = /healthz {
            access_log off;
            return 200 "ok\n";
            add_header Content-Type text/plain;
        }
    }

    # 定义限流区域
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

    # 重定向HTTP到HTTPS
    server {
        listen 80;
        server_name api.example.com;
        return 301 https://$host$request_uri;
    }
}
